rows = [("2025-03-01", "10.00"), ("2025-03-01", "$5.00"), ("2025-03-02", "7.50"), ("2025-03-03", "$2.00"), ("2025-03-03", "3.00")]

def clean_v1(text):
    try:
        return round(float(text) * 100)
    except ValueError:
        return None

def clean_v2(text):
    return clean_v1(text.lstrip("$"))

def totals(rows, clean):
    result = {}
    for day, text in rows:
        cents = clean(text)
        if cents is not None:
            result[day] = result.get(day, 0) + cents
    return result

old, new = totals(rows, clean_v1), totals(rows, clean_v2)
print(sorted(old.items()))
print(sorted(new.items()))
print([d for d in sorted(new) if old.get(d) != new[d]])
